    comp:[["How does Silver take Jim to the treasure?",["Freely","Tied to him with a rope","In a boat","Blindfolded"],1,"Jim says he was led like a dancing bear."],["What do they find on the way?",["Gold","A skeleton arranged as a pointer","A hut","Nothing"],1,"Flint's last joke."],["What do they hear among the trees?",["Nothing","A voice singing Flint's song","A shot","The sea"],1,"And the pirates are terrified."],["Who is really singing?",["Flint's ghost","Ben Gunn","Silver","The doctor"],1,"Silver is the only one who works it out."],["What does that show about Silver?",["He is lucky","He reasons while the others believe","He is superstitious","He is deaf"],1,"His intelligence is his real weapon, not his crutch."],["What is in the hole?",["The gold","A broken pickaxe and old boards","A skeleton","A map"],1,"The treasure is long gone."],["Where is it?",["Sunk","In Ben Gunn's cave","In England","Nobody knows"],1,"He moved it, alone, over many weeks."],["What happens to Long John Silver at the end?",["He is hanged","He escapes with a bag of coins","He is killed","He stays on the island"],1,"Stevenson lets him go on purpose."]],
    tf:[["Jim is led to the treasure on a rope.",true,"Like a dancing bear, he says."],["They find a skeleton pointing the way.",true,"Arranged by Flint himself."],["The voice in the trees is a ghost.",false,"It is Ben Gunn, and Silver knows it."],["The treasure is where the map says.",false,"The hole is empty."],["Ben Gunn had moved the gold years before.",true,"To a cave on the north of the island."],["Silver is caught and punished.",false,"He escapes with about four hundred pounds."]],
    rw:[["Jim was tied to Silver with a rope.",0,"Right — he could not run away."],["The skeleton pointed in the direction of the treasure.",0,"Right — Flint used one of his own men."],["The pirates thought the voice was Flint's ghost.",0,"Right — and they were terrified."],["Silver recognised the voice as Ben Gunn's.",0,"Right — and said so."],["The hole contained a broken pickaxe.",0,"Right — and boards from packing cases."],["Ben Gunn moved the treasure in a single night.",1,"Wrong — it took him many weeks, alone."],["The treasure was worth exactly £700,000.",2,"Doesn't say — no figure is confirmed."],["Silver disappeared at a port in America.",0,"Right — with one bag of coins."]],
